INSERT INTO "reviews" ("id", "tour_id", "booking_code", "user_name", "rating", "comment", "verified", "created_at") VALUES ('5401126c-0ace-4feb-aec1-771dee889eaa', 'ae9870ea-0c95-4eb4-9c3e-9b38f469e263', NULL, 'Nguyễn Thu Trang', 5.0, 'Chuyến săn mây Cầu Đất thật sự tuyệt vời! Biển mây bồng bềnh lúc 5h30 sáng, anh HDV rất nhiệt tình chụp ảnh cho cả đoàn.', TRUE, '2026-10-13 07:25:27.482231') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "tour_id", "booking_code", "user_name", "rating", "comment", "verified", "created_at") VALUES ('5add6aac-e6b7-4889-b90c-ddcd58b6bab8', 'ae9870ea-0c95-4eb4-9c3e-9b38f469e263', NULL, 'Hoàng Minh Quân', 5.0, 'Xe đón đúng giờ, bữa sáng cà phê ngắm đồi chè rất ngon và yên bình. Sẽ rủ bạn bè đi tiếp lần sau.', TRUE, '2026-10-13 07:25:27.482255') ON CONFLICT DO NOTHING;
INSERT INTO "reviews" ("id", "tour_id", "booking_code", "user_name", "rating", "comment", "verified", "created_at") VALUES ('dd511a6f-5465-40e2-9ba5-4a8f933d0ed9', 'aa7e31e6-8398-4554-93e5-8af4050e284d', NULL, 'Trần Bảo Anh', 5.0, 'Thác Pongour mùa này nước đẹp hùng vĩ. Đội ngũ tổ chức chu đáo, trang bị bảo hộ cẩn thận.', TRUE, '2026-10-13 07:25:27.482268') ON CONFLICT DO NOTHING;
